# Arch dependency name -> Gentoo dependency atom.
# Used by bin/scaffold-ebuild and reviewed by hand when ebuilds are finished.
#
# Special values:
#   DROP            the dependency is part of Gentoo's @system / baseline
#                   toolchain (glibc, gcc-libs, coreutils, ...) and is omitted
#   MANUAL:<note>   no mechanical mapping; the ebuild must decide. Currently
#                   unresolved MANUAL entries are printed as warnings during
#                   scaffolding so they cannot be silently dropped.
#
# Keep entries sorted by Arch name. A versioned Arch dependency ("nodejs>=22")
# must either get its own literal entry here or it falls through to MANUAL.

alsa-lib				media-libs/alsa-lib
alsa-utils				media-sound/alsa-utils
apache-utilities		DROP
at-spi2-atk				app-accessibility/at-spi2-core
bat						sys-apps/bat
bash					app-shells/bash
brotli					app-arch/brotli
chromium				www-client/chromium
click					dev-python/click
coreutils				DROP
desktop-file-utils		dev-util/desktop-file-utils
docker					app-containers/docker
dvd+rw-tools			app-cdr/dvd+rw-tools
emacs-wayland			app-editors/emacs[pgtk]
eza						sys-apps/eza
fd						sys-apps/fd
ffmpeg					media-video/ffmpeg
fish					app-shells/fish
fuse2					sys-fs/fuse:0
fzf						app-shells/fzf
glibc					DROP
gcc-libs				DROP
git						dev-vcs/git
gtk3					x11-libs/gtk+:3
gtk4					gui-libs/gtk
hicolor-icon-theme		x11-themes/hicolor-icon-theme
