libgtk-3.so=0			x11-libs/gtk+:3
libpulse				media-libs/libpulse
libsm					x11-libs/libSM
libxkbfile				x11-libs/libxkbfile
libxss					x11-libs/libXScrnSaver
libzip					dev-libs/libzip
lsp-plugins-lv2			media-libs/lsp-plugins
mesa					media-libs/mesa
mise					MANUAL:not in this tree; available in GURU (shipped packages note it in pkg_postinst)
more-itertools			dev-python/more-itertools
mpv						media-video/mpv
neovim					app-editors/neovim
neovim>=0.9.0			>=app-editors/neovim-0.9.0
nodejs					net-libs/nodejs
nodejs>=22				>=net-libs/nodejs-22
nss						dev-libs/nss
openvpn					net-vpn/openvpn
